// Runs once the match result is known.
// isWin is true when the player's team won.
ScBtlResult <- function ()
{
	local isWin = 0;
	isWin = CMND_BTL_GET_RESULT();

	if (isWin)
	{
		// Player's team won: record it and unlock the rematch.
		CMND_SET_GLOBAL_BIT_FLAG(1354, 1);
		OPEN_CPU_BTL_FLAG(1652);
	}
	else
	{
		// Opponent won or draw.
		CMND_SET_GLOBAL_BIT_FLAG(1354, 0);
		CMND_SET_GLOBAL_BIT_FLAG(250, 1);
	}
};

// Pass an array to also get the final score back.
ScBtlResult <- function ()
{
	local score = [0, 0];
	local isWin = CMND_BTL_GET_RESULT(score);
	local playerGoals = score[0];
	local opponentGoals = score[1];

	if (isWin && playerGoals - opponentGoals >= 3)
	{
		// Won by three goals or more.
	}
};
